  assert.equal(issued.error, 'NOT_DRAFT');
});

test('issueInvoice preserves all invoice data', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-06-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 2 },
    ],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const issued = issueInvoice(invoice, ['INV-2026-0050']);
  assert.equal(issued.ok, true);
  assert.equal(issued.value.customerId, 'C-003');
  assert.equal(issued.value.issueDate, '2026-06-15');
  assert.equal(issued.value.lines.length, 2);
  assert.equal(issued.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(issued.value.lines[1].sku, 'LOGO-PACK');
});

test('issueInvoice does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  issueInvoice(invoice, []);
  assert.deepEqual(invoice, invoiceCopy);
});

