test('invoiceTotals with gold tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier = 5%
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // subtotal = 10 * 9500 = 95000
  // discount = 95000 * 5 / 100 = 4750
  // lineAmount = 95000 - 4750 = 90250
  // vat = 90250 * 21 / 100 = 18952.5 -> 18952
  // total = 95000 - 4750 + 18952 = 109202
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 4750,
    vat: 18952,
    total: 109202,
  });
});

test('invoiceTotals with silver tier discount', () => {
  const result = createInvoice({
    customerId: 'C-003', // silver tier = 2.5%
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // subtotal = 10 * 9500 = 95000
  // discount = 95000 * 2.5 / 100 = 2375
  // lineAmount = 95000 - 2375 = 92625
  // vat = 92625 * 21 / 100 = 19451.25 -> 19451
  // total = 95000 - 2375 + 19451 = 112076
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 2375,
    vat: 19451,
    total: 112076,
  });
});

test('invoiceTotals with standard tier discount', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0%
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // subtotal = 10 * 9500 = 95000
  // discount = 95000 * 0 / 100 = 0
  // vat = 95000 * 21 / 100 = 19950
  // total = 95000 + 19950 = 114950
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 0,
    vat: 19950,
    total: 114950,
  });
});

test('invoiceTotals with mixed tier and explicit discounts', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier = 5%
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // uses 5% from tier
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 }, // explicit 20%
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // line 1: subtotal = 95000, discount = 4750, lineAmount = 90250, vat = 18952
  // line 2: subtotal = 120000, discount = 24000, lineAmount = 96000, vat = 20160
  // total discount = 4750 + 24000 = 28750
  // total vat = 18952 + 20160 = 39112
  // total = 215000 - 28750 + 39112 = 225362
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 28750,
    vat: 39112,
    total: 225362,
  });
});

test('applyVoucher applies voucher to draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const voucher = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucher.ok, true);
  assert.equal(voucher.value.voucher.code, 'SAVE10');
  assert.equal(voucher.value.voucher.amount, 10000);
});

test('applyVoucher handles NOT_DRAFT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const invoice = { ...result.value, status: 'issued' };
  const voucher = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucher.ok, false);
  assert.equal(voucher.error, 'NOT_DRAFT');
});

test('applyVoucher handles VOUCHER_EXISTS', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;

  const voucher1 = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucher1.ok, true);
  invoice = voucher1.value;

  const voucher2 = applyVoucher(invoice, { code: 'SAVE20', amount: 20000 });
  assert.equal(voucher2.ok, false);
  assert.equal(voucher2.error, 'VOUCHER_EXISTS');
});

