test('invoiceTotals includes voucher in calculation', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;
  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 0,
    vat: 19950,
    voucher: 10000,
    total: 104950,
  });
});

test('invoiceTotals voucher = 0 when no voucher applied', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals total = subtotal - discount + vat - voucher', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;
  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 5000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 104202);
});

test('voucher is preserved through invoice operations', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;
  assert.equal(invoice.voucher.code, 'SAVE10');

  const issued = issueInvoice(invoice, []);
  assert.equal(issued.ok, true);
  assert.equal(issued.value.voucher.code, 'SAVE10');
  assert.equal(issued.value.voucher.amount, 10000);
});

test('voucher is preserved when adding lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  const addLineResult = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(addLineResult.ok, true);
  assert.equal(addLineResult.value.voucher.code, 'SAVE10');
});

