test('invoiceTotals calculates discount for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // subtotal = 10 * 9500 = 95000
  // discount = 95000 * 10 / 100 = 9500
  // lineAmount = 95000 - 9500 = 85500
  // vat = 85500 * 21 / 100 = 17955
  // total = 95000 - 9500 + 17955 = 103455
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 9500,
    vat: 17955,
    total: 103455,
  });
});

test('invoiceTotals calculates discount for multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // line 1: subtotal = 95000, discount = 9500, lineAmount = 85500, vat = 17955
  // line 2: subtotal = 120000, discount = 24000, lineAmount = 96000, vat = 20160
  // total discount = 9500 + 24000 = 33500
  // total vat = 17955 + 20160 = 38115
  // total = 95000 + 120000 - 33500 + 38115 = 219615
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 33500,
    vat: 38115,
    total: 219615,
  });
});

test('invoiceTotals with 100% discount on one line', () => {
  const result = createInvoice({
    customerId: 'C-001',
