    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 100 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // line 1: subtotal = 95000, discount = 0, lineAmount = 95000, vat = 19950
  // line 2: subtotal = 120000, discount = 120000, lineAmount = 0, vat = 0
  // total discount = 120000
  // total vat = 19950
  // total = 95000 + 120000 - 120000 + 19950 = 114950
  assert.deepEqual(totals, {
    subtotal: 215000,
    discount: 120000,
    vat: 19950,
    total: 114950,
  });
});

