  assert.equal(result2.ok, true);
  assert.equal(result3.ok, true);
  assert.equal(result1.value.customerName, 'Kite & Co');
  assert.equal(result2.value.customerName, 'Kite & Co');
  assert.equal(result3.value.customerName, 'Kite & Co');
});

